(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10 + Math.sin((x+y)*0.01+t*0.5)*8;
  const wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10 + Math.cos((x-y)*0.012-t*0.4)*8;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.7],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.9],
    [80+Math.sin(t*0.45+3)*110, 40+Math.cos(t*0.65+2)*60, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+1)*70, 200+Math.sin(t*0.75+4)*50, 0.05, 2.8, 1.15]
  ];
  let aS=0, iS=0, moire=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave = Math.sin(d*f-t*sp);
    const wave2 = Math.sin(d*f*1.618-t*sp*0.618+0.5);
    aS += (wave+wave2*0.3)*w;
    iS += (Math.sin(d*f*0.7+t*sp*0.6+1.5)+Math.cos(d*f*0.5-t*sp*0.4))*w;
    moire += Math.sin(d*f*2.0-t*sp*1.5)*Math.sin(d*f*1.5+t*sp*0.8)*w*0.4;
  }
  const n=src.length, act=aS/n, inh=iS/n, moir=moire/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.065+t*1.7)*Math.sin(sy*0.055-t*1.3)*0.3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.08-ang*6+t*2.0)*0.15 + Math.cos(dist*0.03+ang*2-t*0.8)*0.2;
  const voronoi = (() => {
    let md=999, sd=999;
    for (let i=0;i<6;i++) {
      const vx=120+Math.sin(i*1.047+t*0.3)*180, vy=60+Math.cos(i*1.047+t*0.25)*100;
      const d=Math.sqrt((sx-vx)**2+(sy-vy)**2);
      if(d<md){sd=md;md=d}else if(d<sd){sd=d}
    }
    return Math.sin((sd-md)*0.3)*0.3;
  })();
  const feed = act*0.6 + bg*0.25 + spiral*0.2 + moir*0.15 + voronoi*0.1;
  const kill = inh*0.5 + bg*0.15 - spiral*0.1;
  const reaction = Math.tanh((feed-kill)*2.5);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const edge = 1.0-Math.min(1, Math.abs(reaction)*3)*0.15;
  const blend = reaction*0.65+cell*0.2+moire*0.08+voronoi*0.07;
  const v = blend*0.5+0.5;
  const lum = 0.75+Math.sin(reaction*Math.PI)*0.25+Math.abs(moir)*0.1;
  const pal = [
    [5,10,45],[10,40,80],[12,75,105],[18,120,130],[25,155,140],
    [140,175,80],[210,190,60],[230,150,55],[215,105,65],
    [185,65,70],[130,35,60],[70,18,50],[30,10,42],[5,10,45]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const bri = lum*(0.9+edge*0.15);
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*bri)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*bri)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*bri)|0
  ];
}
